importScripts('climate-core.js?v=14','sunshine-core.js?v=14');
// Bounded decoded memory. Sunshine bulk responses use no-store, never a disk cache.
let cache=new Map(),activeId;
async function load(url,sun){let c=cache.get(url);if(c)return c;const r=await fetch(url,sun?{cache:'no-store'}:{});if(!r.ok)throw Error('Climate download failed');const buffer=await new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();c=sun?SunshineCore.parse(buffer):ClimateCore.parse(buffer);cache.set(url,c);while(cache.size>4)cache.delete(cache.keys().next().value);return c;}
onmessage=async({data:{period,params,id,files,nodes,sunshine}})=>{activeId=id;try{const score=new Float64Array(nodes),days=new Float64Array(nodes);if(params.sunenabled){const years=period==='mean'?['2020','2021','2022','2023','2024','2025']:[period],list=years.flatMap(year=>sunshine.daily_files[year]),counts=new Uint16Array(nodes),seconds=new Float64Array(nodes),invalid=new Uint8Array(nodes);let calendarDays=0;for(const year of years)calendarDays+=Number(year)%4===0?366:365;for(let i=0;i<list.length;i++){if(activeId!==id)return;const c=await load(sunshine.data_url+list[i],true);if(activeId!==id)return;for(let k=0;k<c.n;k++){const v=SunshineCore.calculate(c,k,params),j=c.start+k;score[j]+=v.scoreSum;days[j]+=v.comfortable;counts[j]+=v.count;seconds[j]+=v.sunSecondsSum;if(!v.eligible)invalid[j]=1;}postMessage({id,progress:(i+1)/list.length,sun:true});}for(let k=0;k<nodes;k++){if(invalid[k]||!counts[k])score[k]=days[k]=seconds[k]=NaN;else{score[k]=Math.min(10,Math.max(0,score[k]/counts[k]));days[k]=days[k]/counts[k]*calendarDays/years.length;seconds[k]=seconds[k]/counts[k]/3600;}}if(activeId===id)postMessage({id,score,days,coverage:counts,sunhours:seconds},[score.buffer,days.buffer,counts.buffer,seconds.buffer]);}else{score.fill(NaN);days.fill(NaN);for(let i=0;i<files.length;i++){if(activeId!==id)return;const c=await load('https://comfy-days-climate-era5.lfsalmeida92.workers.dev/era5-v1/'+files[i],false);if(activeId!==id)return;for(let k=0;k<c.n;k++){const v=ClimateCore.calculate(c,k,params);score[c.start+k]=v[0];days[c.start+k]=v[1];}postMessage({id,progress:(i+1)/files.length});}if(activeId===id)postMessage({id,score,days},[score.buffer,days.buffer]);}}catch(e){if(activeId===id)postMessage({id,error:e.message});}};
